// Junta a avaliação recebida com o motivo dado pela IA e aplica a regra da
// avaliação crítica. A regra é fixa e fica aqui, em código: a IA classifica o
// motivo, mas não decide o que é crítico.
const avaliacao = $('Avaliação nova').item.json.body;
const motivo = $json.output.classificacoes[0].motivo;

const NOMES = {
  nao_recebido: 'Não recebido',
  entrega_incompleta: 'Entrega incompleta',
  produto_errado: 'Produto errado',
  defeito_ou_qualidade: 'Defeito ou qualidade',
  atraso: 'Atraso ou problema na entrega',
  atendimento_e_pos_venda: 'Atendimento e pós-venda',
  elogio: 'Elogio',
  outro: 'Outro',
};

// Mesma regra de src/radar/automacao.py (eh_critica):
// nota 1 ou 2 e um motivo de reclamação identificado.
const nota = Number(avaliacao.nota);
const critica = nota <= 2 && !['elogio', 'outro'].includes(motivo);

return {
  json: {
    review_id: avaliacao.review_id,
    data_avaliacao: avaliacao.data_avaliacao,
    nota,
    categoria: avaliacao.categoria,
    texto: avaliacao.texto,
    motivo,
    motivo_nome: NOMES[motivo],
    critica,
    situacao: critica ? 'aguardando rascunho' : 'registrada',
    rascunho: '',
    processada_em: new Date().toLocaleString('sv-SE', { timeZone: 'America/Sao_Paulo' }),
  },
};

